352→              </div>
353→            ) : (
354→              <>
355→                <QueryEditor
356→                  onExecute={handleQueryExecute}
357→                  initialQuery={editorQuery}
358→                />
359→                {queryResult?.resultType === 'markdown' ? (
360→                  <ResultMarkdown result={queryResult} />
361→                ) : (
362→                  <ResultsTable result={queryResult} />
363→                )}
364→              </>
365→            )}
366→          </main>
367→        </div>
368→      )}
369→    </div>
370→  );
371→}
